codes = ['A12', 'B7', 'X9', 'C3']

for code in codes:
    if len(code) == 2 and code[0].isalpha():
        print('accepted:', code)
        break
    print('rejected:', code)
else:
    print('no valid code found')

n = 5
while n > 0:
    if n == 3:
        n -= 1
        continue
    print('count', n)
    n -= 1

values = [4, 8, 15, 16, 23, 42]

for v in values:
    if v % 5 == 0:
        print('first multiple of 5:', v)
        break
else:
    print('no multiple of 5')

print('--- odds ---')
for v in values:
    if v % 2 == 0:
        continue
    print(v)

count = 0
while count < 3:
    count += 1
    print('pass', count)

practice.solution:
n = int(input())
values = list(map(int, input().split()))
for start in values:
    current = start
    steps = 0
    while current != 1:
        if current % 2 == 0:
            current //= 2
        else:
            current = 3 * current + 1
        steps += 1
    print(start, steps)

